import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ name, userName, userUsername, username, grade, subjects, handleLogout }) {
  const [materials, setMaterials] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  const [allQuestions, setAllQuestions] = useState([]);

  const [activeTab, setActiveTab] = useState('dashboard');
  const [selectedSubjectFilter, setSelectedSubjectFilter] = useState('');
  const [previewMaterial, setPreviewMaterial] = useState(null);

  const [activeExamData, setActiveExamData] = useState(null);
  const [examAnswers, setExamAnswers] = useState({});
  
  // 🧩 Lesson Activity Specific Instances
  const [activityTopics, setActivityTopics] = useState([]);
  const [selectedActivityId, setSelectedActivityId] = useState('');
  const [currentActivityQuestions, setCurrentActivityQuestions] = useState([]);
  const [practiceAnswers, setPracticeAnswers] = useState({});
  const [practiceResult, setPracticeResult] = useState(null);

  const loggedInUsername = username || userUsername || '';
  const loggedInName = name || userName || '';
  const [liveProfile, setLiveProfile] = useState(null);

  useEffect(() => {
    axios.get('http://localhost:8082/api/view-students')
      .then(res => {
        if (Array.isArray(res.data)) {
          const currentStudent = res.data.find(s => 
            (s.username && loggedInUsername && String(s.username).toLowerCase() === String(loggedInUsername).toLowerCase()) ||
            (s.name && loggedInName && String(s.name).toLowerCase() === String(loggedInName).toLowerCase())
          );
          if (currentStudent) setLiveProfile(currentStudent);
        }
      })
      .catch(err => console.error(err));
  }, [loggedInUsername, loggedInName]);

  const displayNameStr = liveProfile ? liveProfile.name : (loggedInName || 'Student');
  const displayGradeStr = liveProfile ? liveProfile.grade : (grade || 'Grade 8');
  const displaySubjectsStr = liveProfile ? liveProfile.subjects : (subjects || 'Mathematics, ICT');
  const mySubjects = displaySubjectsStr ? displaySubjectsStr.split(', ') : ['Mathematics', 'ICT'];

  useEffect(() => {
    if (!displayGradeStr) return;
    
    // Fetch generic handouts
    axios.get('http://localhost:8082/api/learning-materials')
      .then(res => {
        const all = Array.isArray(res.data) ? res.data : [];
        setMaterials(all.filter(m => String(m.grade).toLowerCase() === String(displayGradeStr).toLowerCase()));
      }).catch(() => {});

    // Fetch Formal online examinations
    axios.get('http://localhost:8082/api/quizzes')
      .then(res => {
        const all = Array.isArray(res.data) ? res.data : [];
        setQuizzes(all.filter(q => String(q.grade).toLowerCase() === String(displayGradeStr).toLowerCase()));
      }).catch(() => {});

    // Read full activity registry block
    axios.get('http://localhost:8082/api/lesson-activities')
      .then(res => {
        const allData = Array.isArray(res.data) ? res.data : [];
        const dynamicTopics = [];
        const seen = new Set();
        allData.forEach(item => {
          if (!seen.has(item.lesson_name)) {
            seen.add(item.lesson_name);
            dynamicTopics.push({ id: item.lesson_name, title: item.lesson_name });
          }
        });
        setActivityTopics(dynamicTopics);
      })
      .catch(() => {});

    axios.get('http://localhost:8082/api/question-bank')
      .then(res => setAllQuestions(Array.isArray(res.data) ? res.data : []))
      .catch(() => {});

  }, [displayGradeStr, displaySubjectsStr, activeTab]);

  // Sync questions under selected dynamic lesson assignment
  useEffect(() => {
    if (selectedActivityId) {
      axios.get('http://localhost:8082/api/lesson-activities')
        .then(res => {
          const allData = Array.isArray(res.data) ? res.data : [];
          setCurrentActivityQuestions(allData.filter(q => q.lesson_name === selectedActivityId));
        })
        .catch(err => console.error(err));
    } else {
      setCurrentActivityQuestions([]);
    }
    setPracticeAnswers({});
    setPracticeResult(null);
  }, [selectedActivityId, activeTab]);

  const activeExamQuestions = allQuestions.filter(q => q.quiz_id === parseInt(activeExamData?.id));

  const handlePracticeSubmit = () => {
    let score = 0;
    currentActivityQuestions.forEach(q => {
      const userAns = String(practiceAnswers[q.id] || '').trim().toUpperCase();
      const correctAns = String(q.correct_answer || '').trim().toUpperCase();
      if (userAns === correctAns) score++;
    });
    setPracticeResult({ score, total: currentActivityQuestions.length });
  };

  const getQuestionType = (q) => {
    if (!q.option_a) return 'BLANK';
    if (q.option_a.toUpperCase() === 'TRUE' || q.option_a === 'TRUE') return 'TRUE_FALSE';
    return 'MCQ';
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden', backgroundColor: '#f8fafc', fontFamily: 'sans-serif', width: '100%' }}>
      <div style={styles.sidebar}>
        <div style={{ padding: '0 25px', marginBottom: '40px', textAlign: 'center' }}>
          <h2 style={{ margin: 0, fontSize: '24px' }}>Aura Pen Saku</h2>
          <p style={{ color: '#86efac', margin: '5px 0 0 0', fontSize: '12px', fontWeight: 'bold' }}>STUDENT SYSTEM</p>
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: '5px', padding: '0 15px' }}>
          <button onClick={() => setActiveTab('dashboard')} style={styles.sidebarBtn(activeTab === 'dashboard')}>🏠 Dashboard Overview</button>
          <button onClick={() => setActiveTab('materials')} style={styles.sidebarBtn(activeTab === 'materials')}>📚 Course Learning Materials</button>
          <button onClick={() => setActiveTab('activities')} style={styles.sidebarBtn(activeTab === 'activities')}>🧩 Interactive Lesson Activities</button>
          <button onClick={() => setActiveTab('exams')} style={styles.sidebarBtn(activeTab === 'exams')}>📝 Online Formal Exams</button>
          <button onClick={handleLogout} style={styles.logoutBtn}>Logout Terminal 🚪</button>
        </div>
      </div>

      <div style={{ flex: 1, padding: '40px 50px', overflowY: 'auto' }}>
        
        {activeTab === 'dashboard' && (
          <div style={{ display: 'flex', flexDirection: 'column', gap: '25px' }}>
            <div style={styles.welcomeBanner}>
              <h1 style={{ margin: 0, fontSize: '26px' }}>Welcome back, {displayNameStr}! 🎓</h1>
              <p style={{ margin: '8px 0 0 0', opacity: 0.9, fontSize: '14px' }}>Access your personalized classroom workflows seamlessly via the dashboard navigation interface.</p>
            </div>
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
              <div style={styles.statCard('#7c3aed')}><h4>Assigned Grade Instance</h4><h2>{displayGradeStr}</h2></div>
              <div style={styles.statCard('#ea580c')}><h4>Registered Course Subjects</h4><h2>{displaySubjectsStr}</h2></div>
            </div>
          </div>
        )}

        {activeTab === 'materials' && (
          <div>
            <h3 style={{ color: '#1e293b', fontSize: '20px', margin: '0 0 20px 0' }}>📚 Course Handouts & Media Channels</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
              {materials.map((m, i) => (
                <div key={i} style={styles.materialRow}>
                  <div>
                    <h5 style={{ margin: 0, fontSize: '14.5px' }}>{m.title}</h5>
                    <span style={{ fontSize: '11px', color: '#2563eb', fontWeight: 'bold' }}>{m.subject}</span>
                  </div>
                  <button onClick={() => setPreviewMaterial(m)} style={styles.viewBtn}>Launch Document 📖</button>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeTab === 'activities' && (
          <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #cbd5e1' }}>
            <h3 style={{ color: '#1e293b', fontSize: '20px', margin: '0 0 5px 0' }}>🧩 Interactive Practice Target Sheets</h3>
            <p style={{ color: '#64748b', fontSize: '13px', margin: '0 0 20px 0' }}>Dynamic modules synced from database repositories to track performance metrics.</p>

            <div style={{ marginBottom: '20px', display: 'flex', gap: '10px', alignItems: 'center' }}>
              <span style={{ fontSize: '13px', fontWeight: 'bold' }}>Target Module:</span>
              <select value={selectedActivityId} onChange={(e) => setSelectedActivityId(e.target.value)} style={{ width: '320px', padding: '8px', borderRadius: '6px', border: '1px solid #cbd5e1' }}>
                <option value="">-- Choose Target Assignment Node --</option>
                {activityTopics.map((t, idx) => (
                  <option key={idx} value={t.id}>{t.title}</option>
                ))}
              </select>
            </div>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
              {currentActivityQuestions.map((q, idx) => {
                const type = getQuestionType(q);
                return (
                  <div key={q.id} style={{ paddingBottom: '15px', borderBottom: '1px dashed #f1f5f9' }}>
                    <p style={{ fontWeight: '600', fontSize: '14.5px', color: '#1e293b' }}>({idx + 1}) {q.question_text}</p>
                    
                    {type === 'MCQ' && (
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginTop: '10px' }}>
                        {['A', 'B', 'C', 'D'].map(opt => q[`option_${opt.toLowerCase()}`] && (
                          <label key={opt} style={{ fontSize: '13.5px', display: 'flex', gap: '8px', cursor: 'pointer' }}>
                            <input type="radio" name={`activity_${q.id}`} checked={practiceAnswers[q.id] === opt} onChange={() => setPracticeAnswers({ ...practiceAnswers, [q.id]: opt })} />
                            {opt}) {q[`option_${opt.toLowerCase()}`]}
                          </label>
                        ))}
                      </div>
                    )}

                    {type === 'BLANK' && (
                      <input type="text" placeholder="Type answer evaluation statement..." value={practiceAnswers[q.id] || ''} onChange={(e) => setPracticeAnswers({ ...practiceAnswers, [q.id]: e.target.value })} style={styles.fullInput} />
                    )}

                    {type === 'TRUE_FALSE' && (
                      <div style={{ display: 'flex', gap: '20px', marginTop: '10px' }}>
                        <label style={{ color: '#16a34a', fontWeight: 'bold', display: 'flex', gap: '6px', cursor: 'pointer' }}>
                          <input type="radio" name={`activity_${q.id}`} checked={practiceAnswers[q.id] === 'TRUE'} onChange={() => setPracticeAnswers({ ...practiceAnswers, [q.id]: 'TRUE' })} /> TRUE
                        </label>
                        <label style={{ color: '#b91c1c', fontWeight: 'bold', display: 'flex', gap: '6px', cursor: 'pointer' }}>
                          <input type="radio" name={`activity_${q.id}`} checked={practiceAnswers[q.id] === 'FALSE'} onChange={() => setPracticeAnswers({ ...practiceAnswers, [q.id]: 'FALSE' })} /> FALSE
                        </label>
                      </div>
                    )}
                  </div>
                );
              })}

              {currentActivityQuestions.length > 0 ? (
                <>
                  {practiceResult && (
                    <div style={{ backgroundColor: '#dcfce7', padding: '15px', borderRadius: '10px', color: '#16a34a', fontWeight: 'bold', textAlign: 'center' }}>
                      Performance Summary Score: {practiceResult.score} / {practiceResult.total} ({(practiceResult.score / practiceResult.total * 100).toFixed(0)}%)
                    </div>
                  )}
                  <button onClick={handlePracticeSubmit} style={{ ...styles.btn, backgroundColor: '#6b21a8', width: '100%' }}>Submit Activity Responses</button>
                </>
              ) : (
                selectedActivityId && <p style={{ color: '#94a3b8', textAlign: 'center' }}>No available active query components registered inside this schema.</p>
              )}
            </div>
          </div>
        )}

        {activeTab === 'exams' && (
          <div>
            <h3 style={{ color: '#1e293b', fontSize: '20px', marginBottom: '20px' }}>📝 Formal Examination Assessment Portal</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
              {quizzes.map((q, i) => (
                <div key={i} style={styles.examRow}>
                  <div>
                    <h4 style={{ margin: '0 0 5px 0', fontSize: '15px' }}>{q.title}</h4>
                    <span style={{ color: '#ea580c', backgroundColor: '#fff7ed', padding: '2px 6px', borderRadius: '4px', fontSize: '11px', fontWeight: 'bold' }}>{q.subject_name}</span>
                  </div>
                  <button onClick={() => { setActiveExamData(q); setExamAnswers({}); }} style={styles.startExamBtn}>Launch Paper 🚀</button>
                </div>
              ))}
            </div>
          </div>
        )}

      </div>

      {activeExamData && (
        <div style={styles.modalOverlay}>
          <div style={{ ...styles.modal, width: '700px' }}>
            <div style={styles.modalHeader}>
              <h4>Assessment Scope: {activeExamData.title}</h4>
              <button onClick={() => setActiveExamData(null)} style={styles.closeBtn}>✕ Terminate Test</button>
            </div>
            <div style={{ maxHeight: '440px', overflowY: 'auto', padding: '10px' }}>
              {activeExamQuestions.map((q, idx) => (
                <div key={q.id || idx} style={{ marginBottom: '20px', borderBottom: '1px dashed #cbd5e1', paddingBottom: '15px' }}>
                  <p style={{ fontWeight: 'bold', fontSize: '14.5px' }}>({idx + 1}) {q.question_text}</p>
                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginTop: '10px' }}>
                    {['A', 'B', 'C', 'D'].map(opt => (
                      <label key={opt} style={{ display: 'flex', gap: '8px', fontSize: '13px', cursor: 'pointer' }}>
                        <input type="radio" name={`exam_${q.id}`} checked={examAnswers[q.id] === opt} onChange={() => setExamAnswers({ ...examAnswers, [q.id]: opt })} />
                        {opt}) {q[`option_${opt.toLowerCase()}`]}
                      </label>
                    ))}
                  </div>
                </div>
              ))}
              <button onClick={() => { alert("Examination sheet successfully posted to server database."); setActiveExamData(null); }} style={{ ...styles.btn, backgroundColor: '#ea580c', width: '100%' }}>Finalize Examination</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  sidebar: { width: '260px', backgroundColor: '#145c2e', color: 'white', padding: '30px 0', display: 'flex', flexDirection: 'column', flexShrink: 0 },
  sidebarBtn: (active) => ({ width: '100%', textAlign: 'left', padding: '14px 20px', backgroundColor: active ? 'rgba(255,255,255,0.15)' : 'transparent', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontSize: '14px', fontWeight: active ? 'bold' : 'normal' }),
  logoutBtn: { width: '100%', padding: '12px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer', fontSize: '14px', marginTop: 'auto' },
  welcomeBanner: { backgroundColor: '#15803d', padding: '30px', borderRadius: '15px', color: 'white' },
  statCard: (color) => ({ backgroundColor: 'white', padding: '22px', borderRadius: '15px', borderLeft: `5px solid ${color}`, borderTop: '1px solid #e2e8f0', borderRight: '1px solid #e2e8f0', borderBottom: '1px solid #e2e8f0' }),
  materialRow: { backgroundColor: 'white', padding: '16px 20px', borderRadius: '12px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  viewBtn: { backgroundColor: '#2563eb', color: 'white', padding: '7px 14px', borderRadius: '6px', border: 'none', fontSize: '12px', fontWeight: 'bold', cursor: 'pointer' },
